"""Checks for wormholes_part3_mockup.html (Playwright, no network). Usage: python3 -I test_p3.py <mockup.html>"""
import sys, json, asyncio, re
from playwright.async_api import async_playwright
SEC = "document.querySelector('#whPnSum [data-p3sec]').scrollIntoView()"
res = []
def ok(name, cond):
    res.append((name, bool(cond)))
async def run(path, w, h):
    tag = f'{w}px'
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pg = await b.new_page(viewport={'width': w, 'height': h}, bypass_csp=True, has_touch=(w < 600), is_mobile=(w < 600))
        errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.route('**/*', lambda r: r.abort() if not r.request.url.startswith('file:') else r.continue_())
        await pg.goto('file://' + path); await pg.wait_for_timeout(2500)
        ev = pg.evaluate
        ok(f'{tag} System panel open with a Signatures section', await ev("!!document.querySelector('#whPnSum:not([hidden]) [data-p3sec]')"))
        ok(f'{tag} Connections come before Signatures', await ev("(()=>{const c=document.querySelector('#whPnSum .wh-cnw'),s=document.querySelector('#whPnSum [data-p3sec]');return !!(c&&s&&(c.compareDocumentPosition(s)&Node.DOCUMENT_POSITION_FOLLOWING))})()"))
        ok(f'{tag} Class and Statics come before Connections', await ev("(()=>{const s=document.querySelector('#whPnSum [data-f=\"statics\"]'),c=document.querySelector('#whPnSum .wh-cnw'),k=document.querySelector('#whPnSum [data-f=\"cls\"]');return !!(s&&c&&k&&(s.compareDocumentPosition(c)&Node.DOCUMENT_POSITION_FOLLOWING)&&(k.compareDocumentPosition(s)&Node.DOCUMENT_POSITION_FOLLOWING))})()"))
        ok(f'{tag} statics still saved from its new place', await ev("(()=>{const f=document.querySelector('#whPnSum [data-f=\"statics\"]');f.value='C247';f.dispatchEvent(new Event('change',{bubbles:true}));return whS.st.sys[whFocus()].statics==='C247'})()"))
        cr = "[...document.querySelectorAll('#whPnSum .wh-cnw [data-p3cn]')]"
        cq = lambda k: f"#whPnSum .wh-cnw [data-p3cn=\"{k}\"]"
        ok(f'{tag} Connections in the list (one row each, heading with sort, select-all box)', await ev(f"{cr}.length >= 3 && document.querySelectorAll('#whPnSum .wh-cnw .wh-sgh [data-p3=\"cnsort\"]').length === 4 && !!document.querySelector('#whPnSum [data-p3=\"cnall\"]')"))
        k0 = await ev("(()=>{const l=whS.st.links[0];return whLinkKey(l.a,l.b)})()")
        ok(f'{tag} this side\'s ID and type in the row', await ev(f"document.querySelector('{cq(k0)} .id').textContent==='XYZ-789' && document.querySelector('{cq(k0)} .ty').textContent==='K162'"))
        ok(f'{tag} the other side\'s ID in the row\'s hover', 'other side ABC-123 H296' in await ev(f"document.querySelector('{cq(k0)}').title"))
        ok(f'{tag} an EOL mark on the EOL connection', await ev(f"{cr}.some(r=>r.querySelector('.lf').textContent==='EOL')"))
        if w < 600: ok(f'{tag} phone: Age column hidden, "→" its own 44 px column', await ev("getComputedStyle(document.querySelector('#whPnSum [data-p3cn] .ag')).display==='none' && document.querySelector('#whPnSum [data-p3cn] .go').getBoundingClientRect().width>=43.5"))
        ok(f'{tag} no Copy on connections', not await ev("!!document.querySelector('#whPnSum .wh-cnw [data-p3=\"sgcopy\"]')"))
        nl = await ev("whS.st.links.length")
        tap = (lambda q: pg.tap(q)) if w < 600 else (lambda q: pg.click(q))
        await tap(cq(k0) + ' .id'); await pg.wait_for_timeout(100)
        ok(f'{tag} a click selects a connection', 'Selected: 1' in await ev("document.querySelector('#whPnSum .wh-cnw .wh-sgbar').textContent"))
        await pg.click('#whPnSum [data-p3="cnedit"]'); await pg.wait_for_timeout(100)
        ok(f'{tag} Edit one: this side\'s ID and type, life, mass, size, Drifter, the other side shown', await ev("['sig','type','life','mass','size','dr'].every(k=>!!document.querySelector(`#whPnSum .wh-cnw .wh-sge [data-p3c=\"${k}\"]`)) && document.querySelector('#whPnSum .wh-cnw .wh-sge .ot').textContent.includes('ABC-123')"))
        await pg.select_option('#whPnSum .wh-cnw .wh-sge [data-p3c="mass"]', 'critical'); await pg.click('#whPnSum [data-p3="cnsave"]'); await pg.wait_for_timeout(100)
        ok(f'{tag} Save: mass critical colours the row red, the ID kept', await ev(f"document.querySelector('{cq(k0)}').classList.contains('cm2') && whS.st.links[0].mass==='critical' && document.querySelector('{cq(k0)} .id').textContent==='XYZ-789'"))
        await pg.click('#whPnSum [data-p3="cnall"]'); await pg.wait_for_timeout(100)
        await pg.click('#whPnSum [data-p3="cnedit"]'); await pg.wait_for_timeout(100)
        ok(f'{tag} Edit several: life and mass only', await ev("!!document.querySelector('#whPnSum .wh-cnw .wh-sge [data-p3c=\"life\"]') && !document.querySelector('#whPnSum .wh-cnw .wh-sge [data-p3c=\"sig\"]')"))
        await pg.select_option('#whPnSum .wh-cnw .wh-sge [data-p3c="life"]', 'eol'); await pg.click('#whPnSum [data-p3="cnsave"]'); await pg.wait_for_timeout(100)
        ok(f'{tag} several marked EOL at once', await ev(f"{cr}.every(r=>r.querySelector('.lf').textContent==='EOL')"))
        await pg.click('#whPnSum [data-p3="cnall"]'); await pg.wait_for_timeout(100)
        await pg.click('#whPnSum .wh-cnw .wh-sgh [data-k="to"]'); await pg.wait_for_timeout(100)
        ok(f'{tag} sort connections by system, kept', await ev(f"(()=>{{const a={cr}.map(r=>r.querySelector('.nm .wh-n').textContent);return a.join()===[...a].sort((x,y)=>x.localeCompare(y)).join()}})()") and await ev("JSON.parse(localStorage.getItem('tvWhSecs')).cn.k") == 'to')
        await ev("document.querySelector('#whPnSum .wh-cnw .wh-sgh [data-k=\"f\"]').click()"); await pg.wait_for_timeout(100)   # Age is hidden on a phone (in the hover)
        ko = await ev(f"{cr}.map(r=>r.dataset.p3cn).find(k=>k!=={json.dumps(k0)})")
