        await pg.click('#whPnSum [data-p3="cndel"]'); await pg.wait_for_timeout(100)
        ok(f'{tag} Delete selected connections asks first', 'Delete 1 connection?' in await ev("document.querySelector('#whPnSum .wh-cnw .wh-sgbar').textContent") and await ev("whS.st.links.length") == nl)
        await pg.click('#whPnSum .wh-cnw [data-p3="cfno"]'); await pg.wait_for_timeout(100)
        ok(f'{tag} Cancel keeps it', await ev("whS.st.links.length") == nl)
        await pg.click('#whPnSum [data-p3="cndel"]'); await pg.wait_for_timeout(100); await pg.click('#whPnSum .wh-cnw [data-p3="cfyes"]'); await pg.wait_for_timeout(150)
        ok(f'{tag} Delete removes the connection', await ev("whS.st.links.length") == nl - 1 and not await ev(f"!!document.querySelector('{cq(ko)}')"))
