        await ev("document.querySelector('#whPnSum .wh-rm').scrollIntoView()"); await pg.click('#whPnSum .wh-rm'); await pg.wait_for_timeout(100)
        ok(f'{tag} Remove from the map asks first', await ev("!!document.querySelector('#whPnSum .wh-acts .wh-cf')") and await ev("Object.keys(whS.st.sys).length") == n_sys)
        await pg.click('#whPnSum .wh-acts [data-p3="cfno"]'); await pg.wait_for_timeout(100)
        await ev("document.querySelector('#whPnSum [data-p3sec]').scrollIntoView()")
        # the list (owner 2026-11-17): signal colours, type icons, sortable, select, Copy / Edit / Delete selected
        rows = "[...document.querySelectorAll('#whPnSum [data-p3sec] .wh-sg')]"
        row = lambda i: f"#whPnSum [data-p3sec] .wh-sg[data-p3row=\"{i}\"]"
        ok(f'{tag} list: a heading row with sort buttons and a select-all box', await ev("document.querySelectorAll('#whPnSum [data-p3sec] .wh-sgh [data-p3=\"sort\"]').length === 4 && !!document.querySelector('#whPnSum [data-p3sec] .wh-sgh [data-p3=\"sgall\"]')"))
        ok(f'{tag} colours by the game\'s bands (18% red, 100% green)', await ev(f"document.querySelector('{row('BHV-118')}').classList.contains('b0') && document.querySelector('{row('XYZ-789')}').classList.contains('b3')"))
        for rid in ('RTA-610', 'XYZ-789'):
            ok(f'{tag} game shape drawn in the row\'s colour ({rid})', await ev(f"(()=>{{const c=document.querySelector('{row(rid)} .ic');return !!c.querySelector('svg path')&&getComputedStyle(c).color===getComputedStyle(c.parentNode.querySelector('.id')).color}})()"))
        ok(f'{tag} data shape drawn; partly scanned, type not shown: the game\'s dot', await ev(f"!!document.querySelector('{row('KLM-402')} .ic svg rect') && !!document.querySelector('{row('BHV-118')} .ic svg circle') && !document.querySelector('{row('BHV-118')} .ic .gi')"))
        ok(f'{tag} a kind with no shape yet: the placeholder', await ev("(()=>{const G=JSON.parse(localStorage.getItem('tvWhSigs'));const n=whFocus();G.sys[n].rows.push({id:'STR-001',sg:'Structure',grp:'Citadel',nm:'',pct:100,f:Date.now(),t:Date.now()});localStorage.setItem('tvWhSigs',JSON.stringify(G));whS.pn={};whPaint(true);const ok=!!document.querySelector('#whPnSum [data-p3sec] .wh-sg[data-p3row=\"STR-001\"] .ic .gi.wait');const H=JSON.parse(localStorage.getItem('tvWhSigs'));H.sys[n].rows=H.sys[n].rows.filter(r=>r.id!=='STR-001');localStorage.setItem('tvWhSigs',JSON.stringify(H));whS.pn={};whPaint(true);return ok})()"))
        ok(f'{tag} unknown type reads "not known"', 'not known' in await ev(f"document.querySelector('{row('BHV-118')} .nm').textContent"))
        ok(f'{tag} ages are short (s / min / h / d)', await ev(f"{rows}.every(r=>/^\\d+ (s|min|h|d)$/.test(r.querySelector('.ag').textContent))"))
        ok(f'{tag} default sort: newest first', await ev(f"(()=>{{const a={rows}.map(r=>r.dataset.p3row);return a.indexOf('RTA-610')<a.indexOf('XYZ-789')}})()"))
        ok(f'{tag} nothing selected: Copy / Edit / Delete off', await ev("['sgcopy','sgedit','sgdel'].every(k=>document.querySelector(`#whPnSum [data-p3=\"${k}\"]`).disabled)"))
        ok(f'{tag} the list fits the panel (no sideways scroll)', await ev("(()=>{const t=document.querySelector('#whPnSum [data-p3sec] .wh-sgt'),p=document.querySelector('#whPnSum');return t.scrollWidth<=t.clientWidth+1&&p.scrollWidth<=p.clientWidth+1})()"))
        if w >= 600:
            await pg.click(row('KLM-402') + ' .id'); await pg.wait_for_timeout(100)
            ok(f'{tag} a click selects one row', await ev(f"{rows}.filter(r=>r.getAttribute('aria-selected')==='true').map(r=>r.dataset.p3row).join()") == 'KLM-402')
            await pg.click(row('RTA-610') + ' .id', modifiers=['Control']); await pg.wait_for_timeout(100)
            ok(f'{tag} Ctrl-click adds a row (Selected: 2)', await ev(f"{rows}.filter(r=>r.getAttribute('aria-selected')==='true').length") == 2 and 'Selected: 2' in await ev("document.querySelector('#whPnSum [data-p3sec] .wh-sgbar').textContent"))
            await pg.click(row('XYZ-789') + ' .id'); await pg.wait_for_timeout(100)
            ok(f'{tag} a plain click selects only that one', await ev(f"{rows}.filter(r=>r.getAttribute('aria-selected')==='true').map(r=>r.dataset.p3row).join()") == 'XYZ-789')
            await pg.click(row('KLM-402') + ' .id', modifiers=['Control']); await pg.wait_for_timeout(100)
        else:
            await pg.tap(row('KLM-402') + ' .id'); await pg.wait_for_timeout(100)
            await pg.tap(row('XYZ-789') + ' .id'); await pg.wait_for_timeout(100)
            ok(f'{tag} a tap adds a row (Selected: 2)', await ev(f"{rows}.filter(r=>r.getAttribute('aria-selected')==='true').length") == 2)
            await pg.tap(row('XYZ-789') + ' .id'); await pg.wait_for_timeout(100)
            ok(f'{tag} a second tap takes it off', await ev(f"{rows}.filter(r=>r.getAttribute('aria-selected')==='true').map(r=>r.dataset.p3row).join()") == 'KLM-402')
            await pg.tap(row('XYZ-789') + ' .id'); await pg.wait_for_timeout(100)
        sel2 = await ev(f"{rows}.filter(r=>r.getAttribute('aria-selected')==='true').map(r=>r.dataset.p3row).sort().join()")
        ok(f'{tag} two selected (KLM-402, XYZ-789)', sel2 == 'KLM-402,XYZ-789')
        await ev("navigator.clipboard.writeText=(t)=>{window.__clip=t;return Promise.resolve()}")
        await pg.click('#whPnSum [data-p3="sgcopy"]'); await pg.wait_for_timeout(100)
        clip = await ev("window.__clip||''")
        ok(f'{tag} Copy selected: the game\'s format, one row per line', clip.count('\n') == 1 and 'XYZ-789\tCosmic Signature\tWormhole\tUnstable Wormhole\t100.0%' in clip)
        ok(f'{tag} copied rows read back by the paste reader', await ev(f"(()=>{{const t=window.__clip.split('\\n').map(l=>l.split('\\t'));return t.every(c=>/^[A-Z]{{3}}-\\d{{3}}$/.test(c[0]))}})()"))
        await pg.click('#whPnSum [data-p3="sgedit"]'); await pg.wait_for_timeout(100)
        ok(f'{tag} Edit with two selected: type only', await ev("(()=>{const e=document.querySelector('#whPnSum [data-p3sec] .wh-sge');return !!e&&!!e.querySelector('[data-p3e=\"grp\"]')&&!e.querySelector('[data-p3e=\"id\"]')})()"))
        await pg.click('#whPnSum [data-p3="eno"]'); await pg.wait_for_timeout(100)
        await ev(f"document.querySelector('{row('XYZ-789')}').scrollIntoView()")
        if w >= 600: await pg.click(row('BHV-118') + ' .id')
        else:
            await pg.tap(row('KLM-402') + ' .id'); await pg.tap(row('XYZ-789') + ' .id'); await pg.tap(row('BHV-118') + ' .id')
        await pg.wait_for_timeout(100)
        await pg.click('#whPnSum [data-p3="sgedit"]'); await pg.wait_for_timeout(100)
        ok(f'{tag} Edit with one selected: ID, type and name in place', await ev("['id','grp','nm'].every(k=>!!document.querySelector(`#whPnSum [data-p3sec] .wh-sge [data-p3e=\"${k}\"]`))"))
        await pg.select_option('#whPnSum [data-p3sec] .wh-sge [data-p3e="grp"]', 'Relic Site'); await pg.fill('#whPnSum [data-p3sec] .wh-sge [data-p3e="nm"]', 'Forgotten Perimeter Gateway')
        await pg.click('#whPnSum [data-p3="esave"]'); await pg.wait_for_timeout(100)
        ok(f'{tag} Save keeps the edit (type icon and name)', 'Forgotten Perimeter Gateway' in await ev(f"document.querySelector('{row('BHV-118')} .nm').textContent") and await ev("JSON.parse(localStorage.getItem('tvWhSigs')).sys[whFocus()].rows.find(r=>r.id==='BHV-118').grp") == 'Relic Site')
        ok(f'{tag} the relic shape once the type is set', await ev(f"!!document.querySelector('{row('BHV-118')} .ic svg circle')"))
        await pg.click('#whPnSum [data-p3sec] .wh-sgh [data-k="id"]'); await pg.wait_for_timeout(100)
        ok(f'{tag} sort by ID (A→Z), kept in tvWhSigs', await ev(f"(()=>{{const a={rows}.map(r=>r.dataset.p3row);return a.join()===[...a].sort().join()}})()") and await ev("JSON.parse(localStorage.getItem('tvWhSigs')).sort.k") == 'id')
        await pg.click('#whPnSum [data-p3sec] .wh-sgh [data-k="id"]'); await pg.wait_for_timeout(100)
